(6561296, 975876, 19825, '<td valign="top">I loved this shot -- the perspective, the general composition, the tones and textures. Fascinating shot. It makes me want to take more risks behind the camera. Thanks.</td>', 'I loved this shot -- the perspective, the general composition, the tones and textures. Fascinating shot. It makes me want to take more risks behind the camera. Thanks.', '2011-10-05 11:52:33.000000', NULL, 0),
(6561298, 975758, 19825, '<td valign="top">I can think of no better word for this than Johanna''s "ephemeral". I would treasure this one if this was me and my child.</td>', 'I can think of no better word for this than Johanna''s "ephemeral". I would treasure this one if this was me and my child.', '2011-10-05 11:56:34.000000', NULL, 0),
(6561299, 975944, 75713, '<td valign="top">I love this shot and I can see from the comments you got that others saw just how perfect it was as well.  :)</td>', 'I love this shot and I can see from the comments you got that others saw just how perfect it was as well.  :)', '2011-10-05 11:57:12.000000', NULL, 0),
(6561304, 975823, 19825, '<td valign="top">Something is seriously wrong here. This should have been in the <i><b>top </b></i>20 rather than the bottom 20. Sorry for the error. Nice shot.</td>', 'Something is seriously wrong here. This should have been in the top 20 rather than the bottom 20. Sorry for the error. Nice shot.', '2011-10-05 12:01:18.000000', NULL, 0),
(6561316, 975758, 12611, '<td valign="top">Having children, I understand the feeling of love and wanting to capture the moment of a hug. This was a nine for me , I like the shot, and it was interesting how you achieved it.<br/><br/><i>Message edited by author 2011-10-05 11:14:46.</i></td>', 'Having children, I understand the feeling of love and wanting to capture the moment of a hug. This was a nine for me , I like the shot, and it was interesting how you achieved it.', '2011-10-05 12:09:41.000000', '2011-10-05 12:14:46.000000', 0),
(6561321, 975096, 77196, '<td valign="top">Even before reading your comment, I was thinking - Wow! That boy is growing up! Guess there should be a visual difference between 5 and 9...<br/>Love the lighting, your son''s youth and innocence, and the intensity of your look.</td>', 'Even before reading your comment, I was thinking - Wow! That boy is growing up! Guess there should be a visual difference between 5 and 9...Love the lighting, your son''s youth and innocence, and the intensity of your look.', '2011-10-05 12:11:03.000000', NULL, 0),
(6561328, 975911, 77196, '<td valign="top">This makes me smile! What a wonderful capture. The DOF seems to add a lot to the picture, and gives me a feeling of the transience of this time in your lives, while at the same time the image overall gives a sense of the strong bond between you.</td>', 'This makes me smile! What a wonderful capture. The DOF seems to add a lot to the picture, and gives me a feeling of the transience of this time in your lives, while at the same time the image overall gives a sense of the strong bond between you.', '2011-10-05 12:15:42.000000', NULL, 0),
(6561332, 975553, 19825, '<td valign="top">I loved this shot. Great tones and light. Beautiful. Should have scored much higher. Nice shot. Glad it at least got a little PH recognition.</td>', 'I loved this shot. Great tones and light. Beautiful. Should have scored much higher. Nice shot. Glad it at least got a little PH recognition.', '2011-10-05 12:17:40.000000', NULL, 0),
(6561335, 975962, 77196, '<td valign="top">Ah! The life-long question of twins. This is a great shot, and you both have great expressions.</td>', 'Ah! The life-long question of twins. This is a great shot, and you both have great expressions.', '2011-10-05 12:18:36.000000', NULL, 0),
(6561338, 975662, 19825, '<td valign="top">Lovely, much under rated, shot. I gave it a 7.</td>', 'Lovely, much under rated, shot. I gave it a 7.', '2011-10-05 12:19:58.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6561344, 974629, 19825, '<td valign="top">Love the grain, tones and the two overlapping heads. Nice shot that should have scored higher.</td>', 'Love the grain, tones and the two overlapping heads. Nice shot that should have scored higher.', '2011-10-05 12:21:18.000000', NULL, 0),
(6561349, 975625, 77196, '<td valign="top">This makes me sad, and I wonder what the back story is. To me, this feels like two people choosing to be unhappy despite their accomplishments and relationships. Both look like they''re frustrated because they''re not getting what they want / expect, rather than choosing to cherish and enjoy what they have. Like I said, it makes me feel sad. <br/></td>', 'This makes me sad, and I wonder what the back story is. To me, this feels like two people choosing to be unhappy despite their accomplishments and relationships. Both look like they''re frustrated because they''re not getting what they want / expect, rather than choosing to cherish and enjoy what they have. Like I said, it makes me feel sad. ', '2011-10-05 12:23:21.000000', NULL, 0),
